// Read reads up to len(p) bytes from the PackData channel into p, an error can
// be return if an error happens when reading or if a message is sent in the
// ErrorMessage channel.
//
// When a ProgressMessage is read, is not copy to b, instead of this is written
// to the Progress
//
// Read will return io.EOF when a flush packet is received after reading all
// the PackData channel data.
//
// After Read returns an error, including io.EOF, later calls return the same
// error without reading from the underlying reader, so any data following
// the flush-pkt is left unread.
func (d *Demuxer) Read(b []byte) (read int, err error) {
	if d.err != nil {
		return 0, d.err
	}

	req := len(b)
	for read < req {
		n, err := d.doRead(b[read:req])
		read += n

		if err != nil {
			d.err = err
			return read, err
		}
	}

	return read, nil
}

func (d *Demuxer) doRead(b []byte) (int, error) {
	if len(d.pending) > 0 {
		n := copy(b, d.pending)
		d.pending = d.pending[n:]
		return n, nil
	}

	read, err := d.nextPackData()
	n := copy(b, read)
	// The scanner keeps read valid until its next Scan, which happens only
	// once pending is drained, so the rest of the packet is not copied.
	d.pending = read[n:]

	return n, err
}

func (d *Demuxer) nextPackData() ([]byte, error) {
	if !d.s.Scan() {
		if err := d.s.Err(); err != nil {
			return nil, err
		}
		return nil, io.EOF
	}

	l := d.s.Len()
	if l == pktline.Flush {
		return nil, io.EOF
	} else if l > d.max {
		return nil, ErrMaxPackedExceeded
	}

	content := d.s.Bytes()
	if len(content) < 1 {
		return nil, fmt.Errorf("invalid sideband pktline %04x %q", l, content)
	}

	switch Channel(content[0]) {
	case PackData:
		return content[1:], nil
	case ProgressMessage:
		if d.Progress != nil {
			_, err := d.Progress.Write(sanitize(content[1:], true))
			return nil, err
		}
	case ErrorMessage:
		return nil, fmt.Errorf("unexpected error: %s", sanitize(content[1:], false))
	default:
		return nil, fmt.Errorf("unknown channel %s", sanitize(content, false))
	}

	return nil, nil
}

// sanitize returns message with each control character replaced by its caret
// notation (^[ for ESC, ^A for 0x01, ^? for DEL), keeping the tab and line feed
// and the ANSI SGR sequences that color the output. Carriage return is kept
// only when keepCR is true, for the progress channel where it redraws the
// current line. It returns message itself when it contains no control bytes.
//
// The bytes on the progress and error channels are whatever the server, or a
// hook running on it, wrote to stderr, and they end up on the user's terminal.
// An escape sequence there can redraw the screen, hide what was printed before
// it, or type into the input buffer (CWE-150). Git masks the sideband the same
// way by default, see strbuf_add_sanitized in sideband.c[1]. That function
// masks carriage return, and Git keeps it on the progress channel by splitting
// lines before masking them.
package transport

import (
	"context"
	"io"

	internal "github.com/go-git/go-git/v6/internal/transport"
	"github.com/go-git/go-git/v6/plumbing/format/packfile"
	"github.com/go-git/go-git/v6/plumbing/protocol/capability"
	"github.com/go-git/go-git/v6/plumbing/protocol/packp"
	"github.com/go-git/go-git/v6/plumbing/protocol/packp/sideband"
	"github.com/go-git/go-git/v6/storage"
	"github.com/go-git/go-git/v6/utils/ioutil"
)

// FetchPack fetches a packfile from the remote into the given storage.
//
// caps must be the capabilities the fetch was negotiated with: as
// [NegotiatePack] requests side-band only when req.Progress is set, packf is
// read as multiplexed only when caps support side-band and req.Progress is
// non-nil. A multiplexed response is read up to its closing flush-pkt, and
// an error the remote sends on the error band, even after the pack, fails
// the fetch. So does pack data the storage left unread after the pack
// trailer, although the pack is then already stored. Otherwise packf may be
// left unread past the pack trailer.
//
// FetchPack closes packf before it returns, whether or not the fetch fails,
// unless cancelling ctx ended a read of packf. That read may still be
// blocked, so packf is then left open, and the caller should tie it to ctx so
// that cancelling ctx also closes it.
func FetchPack(
	ctx context.Context,
	st storage.Storer,
	caps capability.List,
	packf io.ReadCloser,
	shallowInfo *packp.ShallowUpdate,
	req *FetchRequest,
) error {
	packf = ioutil.NewContextReadCloser(ctx, packf)

	var demuxer *sideband.Demuxer
	var reader io.Reader = packf
	if caps.Supports(capability.Sideband64k) {
		demuxer = sideband.NewDemuxer(sideband.Sideband64k, reader)
	} else if caps.Supports(capability.Sideband) {
		demuxer = sideband.NewDemuxer(sideband.Sideband, reader)
	}

	// Sideband is only requested when there is progress to report (see
	// NegotiatePack), so only then is the response muxed.
	muxed := demuxer != nil && req.Progress != nil
	if muxed {
		demuxer.Progress = req.Progress
		reader = demuxer
	}

	// A filtered fetch deliberately leaves out objects, so the pack has to be
	// recorded as coming from a promisor remote. Git otherwise reads those
	// absences as corruption: fsck reports broken links to them and gc fails
	// with "unable to read".
	//
	// The marker is left empty. Git fills it with the refs it sought on this
	// path (fetch-pack.c create_promisor_file) and leaves it empty when
	// repacking (repack-promisor.c), and accepts either, because only the
	// file's presence is ever consulted — packfile.c tests it with access(2)
	// and never opens it.
	var err error
	if req.Filter != "" {
		err = packfile.UpdatePromisorObjectStorage(st, reader, "")
	} else {
